import { motion } from 'framer-motion';
import clsx from 'clsx';
import './AcidProgress.css';

export interface AcidProgressProps {
    value: number; // 0 to 100
    max?: number;
    showLabel?: boolean;
    className?: string;
    variant?: 'default' | 'brand' | 'success' | 'warning';
}

export const AcidProgress = ({
    value,
    max = 100,
    showLabel = false,
    className,
    variant = 'default'
}: AcidProgressProps) => {
    const percentage = Math.min(Math.max((value / max) * 100, 0), 100);

    return (
        <div className={clsx('ac-progress-container', className)}>
            {showLabel && (
                <div className="ac-progress-header">
                    <span className="ac-progress-label">STATUS_UPDATE</span>
                    <span className="ac-progress-value">{Math.round(percentage)}%</span>
                </div>
            )}
            <div className="ac-progress-track">
                <motion.div
                    className={clsx('ac-progress-bar', `ac-variant-${variant}`)}
                    initial={{ width: 0 }}
                    animate={{ width: `${percentage}%` }}
                    transition={{ type: 'spring', stiffness: 100, damping: 20 }}
                />
            </div>
        </div>
    );
};

.ac-progress-container {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.ac-progress-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
}

.ac-progress-label {
    font-family: var(--font-mono);
    font-size: 0.65rem;
    color: var(--ac-text-muted);
    letter-spacing: 0.1em;
}

.ac-progress-value {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--ac-text-primary);
}

.ac-progress-track {
    height: 8px;
    background: var(--ac-surface);
    border: 1px solid var(--ac-border-muted);
    border-radius: var(--ac-radius-full);
    overflow: hidden;
    position: relative;
}

.ac-progress-bar {
    height: 100%;
    background: var(--ac-text-primary);
    border-radius: var(--ac-radius-full);
}

.ac-variant-brand {
    background: var(--ac-brand);
}

.ac-variant-success {
    background: #4caf50;
}

.ac-variant-warning {
    background: #ff9800;
}

[data-theme='light'] .ac-progress-track {
    background: #f0f0f0;
}
